import { FormEvent, useCallback, useEffect, useState } from "react";
import type { Session } from "@supabase/supabase-js";
import { getSessionMode, isSupabaseConfigured, setSessionMode, supabase } from "./lib/supabase";
import { starterProducts } from "./starterProducts";

type WorkLocation = { id:string; name:string; active:boolean };
type Employee = { id:string; user_id?:string|null; name:string; email:string; role:"employee"|"admin"; active:boolean; work_location_id:string };
type Campaign = { id:string; label:string; budget:number; base_budget:number; carryover_enabled:boolean; retain_unused_budget:boolean; carryover_amount:number; carryover_from:string|null; work_location_id:string; nomination_limit:number; vote_limit:number; start_at:string; nomination_deadline:string; voting_deadline:string; purchase_at:string; status:string };
type Product = { id:string; brand:string; name:string; category:string; size:string; reference_price:number|null; image_path:string|null; origin:"catalog"|"employee"; approval_status:string; active:boolean; deleted_at:string|null };
type ProductCategory = { id:string; name:string; sort_order:number };
type CampaignMember = { id:string; campaign_id:string; employee_id:string; name_snapshot:string; email_snapshot:string; active:boolean };
type Nomination = { id:string; campaign_id:string; product_id:string; employee_id:string; nominator_name:string; created_at:string };
type Vote = { id:string; campaign_id:string; product_id:string; employee_id:string; voter_name:string; kind:"nomination"|"regular"; created_at:string };
type Comment = { id:string; campaign_id:string; product_id:string; employee_id:string; author_name:string; body:string; created_at:string };
type PurchaseItem = { id:string; campaign_id:string; product_id:string; rank:number; vote_count:number; unit_price:number; suggested_quantity:number; final_quantity:number|null; purchased:boolean; note:string|null };
type Phase = "upcoming"|"nomination"|"voting"|"results"|"purchase";
type ProductSort = "smart"|"votes"|"name"|"price-asc"|"price-desc";

const icons:Record<string,string>={洋芋片:"◒",餅乾:"▦",巧克力:"◆",糖果果凍:"●",米果:"❋",堅果果乾:"♧",海苔肉乾:"▤",飲料:"◫"};
const tones=["tone-1","tone-2","tone-3","tone-4","tone-5","tone-6"];

function phaseOf(c:Campaign):Phase { const now=Date.now(); if(now<+new Date(c.start_at))return"upcoming";if(now<+new Date(c.nomination_deadline))return"nomination";if(now<+new Date(c.voting_deadline))return"voting";if(now<+new Date(c.purchase_at))return"results";return"purchase" }
function shortDate(value:string){return new Intl.DateTimeFormat("zh-TW",{month:"numeric",day:"numeric"}).format(new Date(value))}
function dateTimeInput(value:string){const d=new Date(value);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)}
function errorText(error:unknown){return error instanceof Error?error.message:"操作失敗，請稍後再試"}
function productImageUrl(path:string|null){return path?supabase.storage.from("product-images").getPublicUrl(path).data.publicUrl:""}
async function uploadProductImage(file:File,employeeId:string){if(file.size>5*1024*1024)throw new Error("圖片不可超過 5MB");if(!["image/jpeg","image/png","image/webp","image/gif"].includes(file.type))throw new Error("僅支援 JPG、PNG、WebP 或 GIF 圖片");const ext=(file.name.split(".").pop()||"jpg").toLowerCase().replace(/[^a-z0-9]/g,"");const path=`${employeeId}/${crypto.randomUUID()}.${ext||"jpg"}`;const {error}=await supabase.storage.from("product-images").upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;return path}
function readFormDraft(key:string){try{return JSON.parse(sessionStorage.getItem(key)||"{}") as Record<string,string>}catch{return{}}}
function saveFormDraft(key:string,form:HTMLFormElement){const draft:Record<string,string>={};new FormData(form).forEach((value,name)=>{if(typeof value==="string")draft[name]=value});sessionStorage.setItem(key,JSON.stringify(draft))}
type ConfirmOptions={title:string;items:string[];confirmLabel?:string;danger?:boolean};
function useConfirmDialog(){const [dialog,setDialog]=useState<(ConfirmOptions&{resolve:(value:boolean)=>void})|null>(null);const ask=(options:ConfirmOptions)=>new Promise<boolean>(resolve=>setDialog({...options,resolve}));const close=(answer:boolean)=>{dialog?.resolve(answer);setDialog(null)};const element=dialog?<div className="confirm-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)close(false)}}><section className={`confirm-card ${dialog.danger?"danger":""}`} role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><span className="confirm-icon">{dialog.danger?"!":"✓"}</span><h2 id="confirm-title">{dialog.title}</h2><div className="confirm-items">{dialog.items.map((item,index)=><p key={index}>{item}</p>)}</div><div className="confirm-actions"><button onClick={()=>close(false)}>取消</button><button className="confirm-primary" onClick={()=>close(true)}>{dialog.confirmLabel??"確認"}</button></div></section></div>:null;return{ask,element}}

export default function App(){
  const [session,setSession]=useState<Session|null>(null);
  const [employee,setEmployee]=useState<Employee|null>(null);
  const [loading,setLoading]=useState(true);
  const [denied,setDenied]=useState(false);
  const [route,setRoute]=useState(()=>location.hash||"#/");

  useEffect(()=>{
    if(!isSupabaseConfigured){setLoading(false);return}
    supabase.auth.getSession().then(({data})=>setSession(data.session));
    const {data}=supabase.auth.onAuthStateChange((_event,next)=>setSession(next));
    return()=>data.subscription.unsubscribe();
  },[]);

  useEffect(()=>{
    const handleRouteChange=()=>setRoute(location.hash||"#/");
    window.addEventListener("hashchange",handleRouteChange);

    return()=>window.removeEventListener("hashchange",handleRouteChange);
  },[]);

  useEffect(()=>{if(!session||getSessionMode()!=="shared")return;let timer=0;let lastReset=0;const signOutForIdle=()=>void supabase.auth.signOut();const reset=()=>{const now=Date.now();if(now-lastReset<15000)return;lastReset=now;window.clearTimeout(timer);timer=window.setTimeout(signOutForIdle,30*60*1000)};const events=["pointerdown","keydown","touchstart","scroll"] as const;events.forEach(event=>window.addEventListener(event,reset,{passive:true}));reset();return()=>{window.clearTimeout(timer);events.forEach(event=>window.removeEventListener(event,reset))}},[session?.user.id]);

  useEffect(()=>{
    if(!session){setEmployee(null);setDenied(false);setLoading(false);return}
    setLoading(true);
    supabase.from("employees").select("id,name,email,role,active,work_location_id").eq("user_id",session.user.id).maybeSingle()
      .then(({data,error})=>{setEmployee(data as Employee|null);setDenied(!data||Boolean(error));setLoading(false)});
  },[session?.user.id]);

  if(!isSupabaseConfigured)return <SetupScreen/>;
  if(loading)return <main className="loading-screen">正在確認公司名單…</main>;
  if(!session)return <Login/>;
  if(denied||!employee)return <Unauthorized email={session.user.email??""}/>;
  const adminRoute=route.startsWith("#/admin");
  if(adminRoute&&employee.role!=="admin")return <Unauthorized email={employee.email} adminOnly/>;
  return adminRoute?<AdminApp employee={employee}/>:<EmployeeApp employee={employee}/>;
}

function SetupScreen(){return <main className="system-card"><p className="section-kicker">連線設定</p><h1>網站程式已準備連接 Supabase</h1><p>請建立 <code>.env.local</code>，填入 Project URL 與 Publishable Key，再重新啟動網站。</p><code>VITE_SUPABASE_URL=...<br/>VITE_SUPABASE_PUBLISHABLE_KEY=...</code></main>}

function Login(){
  const [email,setEmail]=useState("");
  const [token,setToken]=useState("");
  const [step,setStep]=useState<"email"|"otp">("email");
  const [busy,setBusy]=useState(false);
  const [message,setMessage]=useState("");
  const [error,setError]=useState(false);
  const [shared,setShared]=useState(()=>getSessionMode()==="shared");
  const [resendIn,setResendIn]=useState(0);

  useEffect(()=>{
    if(resendIn<=0)return;
    const timer=window.setInterval(()=>setResendIn(value=>Math.max(0,value-1)),1000);
    return()=>window.clearInterval(timer);
  },[resendIn]);

  function applySessionMode(){setSessionMode(shared?"shared":"personal")}
  function showError(text:string){setError(true);setMessage(text)}

  async function sendOtp(e?:FormEvent){
    e?.preventDefault();
    setBusy(true);setMessage("");setError(false);
    const normalized=email.trim().toLowerCase();
    applySessionMode();
    const allowed=await supabase.rpc("is_login_email_allowed",{p_email:normalized});
    if(allowed.error){setBusy(false);return showError("目前無法確認員工名單，請稍後再試或聯絡管理者。")}
    if(!allowed.data){setBusy(false);return showError("此 Email 不在啟用的員工名單中，系統不會寄出驗證碼。")}
    const {error}=await supabase.auth.signInWithOtp({email:normalized,options:{shouldCreateUser:true}});
    setBusy(false);
    if(error)return showError(error.message.includes("rate limit")?"驗證碼寄送次數過於頻繁，請稍後再試。":error.message);
    setEmail(normalized);setToken("");setStep("otp");setResendIn(60);
    setMessage("六位數驗證碼已寄出，請查看信箱。");
  }

  async function verify(e:FormEvent){
    e.preventDefault();
    if(!/^\d{6}$/.test(token))return showError("請輸入信件中的六位數驗證碼。");
    setBusy(true);setMessage("");setError(false);applySessionMode();
    const {error}=await supabase.auth.verifyOtp({email:email.trim().toLowerCase(),token,type:"email"});
    setBusy(false);
    if(error)return showError("驗證碼錯誤或已失效，請重新確認或再寄一次。");
  }

  const deviceControl=<button type="button" className={`shared-device ${shared?"selected":""}`} role="switch" aria-checked={shared} onClick={()=>setShared(x=>!x)}><span>共用電腦</span><strong>{shared?"已開啟":"未開啟"}</strong><small>{shared?"關閉分頁即清除登入；閒置 30 分鐘也會自動登出。":"個人電腦會安全保留登入，之後可直接開啟使用。"}</small></button>;

  return <main className="auth-shell">
    <section className="auth-brand-panel">
      <div className="brand"><span className="brand-mark">S</span><div><strong>Snack Vote</strong><small>公司零食共選</small></div></div>
      <div className="auth-copy"><p className="section-kicker">MONTHLY SNACK CLUB</p><h1>把想吃的，<br/>變成下個月的零食。</h1><p>同仁提名、公開具名投票，再依預算產生採購建議。規則透明，選擇也更有參與感。</p></div>
      <div className="auth-flow"><span>01 提名</span><span>02 投票</span><span>03 結果揭曉</span><span>04 安排採購</span></div>
    </section>
    <section className="auth-panel">
      <div className="auth-tools"><TextSizeControl/></div>
      <div className="auth-card">
        <p className="section-kicker">EMPLOYEE SIGN IN</p>
        {step==="email"&&<form onSubmit={sendOtp}>
          <h2>使用公司 Email 登入</h2>
          <p>不需要密碼。輸入員工名單中的 Email，我們會寄送六位數驗證碼。</p>
          <label>Email<input type="email" required autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@company.com" autoFocus/></label>
          {deviceControl}
          <button className="auth-submit" disabled={busy}>{busy?"寄送中…":"寄送六位數驗證碼"}</button>
        </form>}
        {step==="otp"&&<form onSubmit={verify}>
          <button type="button" className="auth-back" onClick={()=>{setStep("email");setToken("");setMessage("");setError(false)}}>← 修改 Email</button>
          <h2>輸入驗證碼</h2>
          <p>驗證碼已寄到 <strong>{email}</strong>。請在有效時間內完成登入。</p>
          <label>六位數驗證碼<input className="otp-input" type="text" required inputMode="numeric" autoComplete="one-time-code" maxLength={6} pattern="[0-9]{6}" value={token} onChange={e=>setToken(e.target.value.replace(/\D/g,"").slice(0,6))} placeholder="000000" autoFocus/></label>
          <button className="auth-submit" disabled={busy||token.length!==6}>{busy?"驗證中…":"驗證並登入"}</button>
          <button type="button" className="resend-code" disabled={busy||resendIn>0} onClick={()=>void sendOtp()}>{resendIn>0?`${resendIn} 秒後可重新寄送`:"重新寄送驗證碼"}</button>
        </form>}
        {message&&<p className={`auth-message ${error?"error":""}`}>{message}</p>}
        <small className="auth-note">系統只會寄信給啟用名單中的 Email。個人電腦會保留登入；共用裝置請開啟共用模式。</small>
      </div>
    </section>
  </main>
}

function TextSizeControl(){const [large,setLarge]=useState(()=>localStorage.getItem("snack-vote-text-size")==="large");useEffect(()=>{document.documentElement.dataset.textSize=large?"large":"comfortable";localStorage.setItem("snack-vote-text-size",large?"large":"comfortable")},[large]);return <div className="text-size-control" aria-label="文字大小"><span>文字</span><button type="button" className={!large?"active":""} onClick={()=>setLarge(false)}>一般</button><button type="button" className={large?"active":""} onClick={()=>setLarge(true)}>放大</button></div>}

function Unauthorized({email,adminOnly=false}:{email:string;adminOnly?:boolean}){return <main className="system-card"><p className="section-kicker">ACCESS CONTROL</p><h1>{adminOnly?"這個頁面僅限管理者":"此 Email 不在啟用名單中"}</h1><p>{email}</p><p>{adminOnly?"你仍可回到員工頁面。":"請聯絡管理者確認名單，完成後重新登入。"}</p><button className="auth-submit" onClick={()=>adminOnly?location.hash="#/":supabase.auth.signOut()}>{adminOnly?"回員工頁面":"登出"}</button></main>}

function EmployeeApp({employee}:{employee:Employee}){
  const {ask:askConfirm,element:confirmElement}=useConfirmDialog();
  const [campaign,setCampaign]=useState<Campaign|null>(null);const [products,setProducts]=useState<Product[]>([]);const [productCategories,setProductCategories]=useState<ProductCategory[]>([]);const [nominations,setNominations]=useState<Nomination[]>([]);const [votes,setVotes]=useState<Vote[]>([]);const [comments,setComments]=useState<Comment[]>([]);const [busy,setBusy]=useState(true);const [query,setQuery]=useState("");const [category,setCategory]=useState("全部");const [sortMode,setSortMode]=useState<ProductSort>("smart");const [draftNominations,setDraftNominations]=useState<string[]>([]);const [toast,setToast]=useState("");const [customOpen,setCustomOpen]=useState(()=>Object.keys(readFormDraft("snack-vote-custom-product-draft")).length>0);const [commentDrafts,setCommentDrafts]=useState<Record<string,string>>({});
  const load=useCallback(async(silent=false)=>{if(!silent)setBusy(true);const {data:c}=await supabase.from("campaigns").select("*").eq("status","active").order("start_at",{ascending:true});const all=(c??[]) as Campaign[];const now=Date.now();const current=[...all].reverse().find(x=>+new Date(x.start_at)<=now)??all[0]??null;setCampaign(current);if(!current){setBusy(false);return}const [{data:p},{data:ca},{data:n},{data:v},{data:co}]=await Promise.all([supabase.from("products").select("*").eq("active",true).is("deleted_at",null).order("category"),supabase.from("product_categories").select("id,name,sort_order").order("sort_order").order("name"),supabase.from("nominations").select("*").eq("campaign_id",current.id),supabase.from("votes").select("*").eq("campaign_id",current.id),supabase.from("comments").select("*").eq("campaign_id",current.id).is("deleted_at",null).order("created_at")]);setProducts((p??[]) as Product[]);setProductCategories((ca??[]) as ProductCategory[]);setNominations((n??[]) as Nomination[]);setVotes((v??[]) as Vote[]);setComments((co??[]) as Comment[]);setDraftNominations(((n??[]) as Nomination[]).filter(x=>x.employee_id===employee.id).map(x=>x.product_id));setBusy(false)},[employee.id]);
  useEffect(()=>{void load(false)},[load]);
  useEffect(()=>{if(!campaign)return;const channel=supabase.channel(`campaign-${campaign.id}`).on("postgres_changes",{event:"*",schema:"public"},()=>void load(true)).subscribe();return()=>{void supabase.removeChannel(channel)}},[campaign?.id,load]);
  useEffect(()=>{if(!customOpen)return;const form=document.querySelector<HTMLFormElement>("form.custom-product-form");if(!form)return;const draft=readFormDraft("snack-vote-custom-product-draft");Object.entries(draft).forEach(([name,value])=>{const field=form.elements.namedItem(name);if(field instanceof HTMLInputElement||field instanceof HTMLSelectElement||field instanceof HTMLTextAreaElement){if(field.type!=="file")field.value=value}});const save=()=>saveFormDraft("snack-vote-custom-product-draft",form);form.addEventListener("input",save);form.addEventListener("change",save);return()=>{form.removeEventListener("input",save);form.removeEventListener("change",save)}},[customOpen]);
  function notify(message:string){setToast(message);setTimeout(()=>setToast(""),2600)}
  if(busy)return <main className="loading-screen">同步本月零食清單…</main>;
  if(!campaign)return <ShellHeader employee={employee}><section className="empty-campaign"><h2>本期活動尚未建立</h2><p>請等待管理者設定本月日期、預算與參與名單。</p></section></ShellHeader>;
  const phase=phaseOf(campaign);const myVotes=votes.filter(v=>v.employee_id===employee.id);const categories=["全部",...(productCategories.length?productCategories.map(c=>c.name):[...new Set(products.map(p=>p.category))])];const nominatedProducts=new Set(nominations.map(n=>n.product_id));
  const voteCount=(productId:string)=>votes.filter(v=>v.product_id===productId).length;const rankedProducts=products.filter(p=>nominatedProducts.has(p.id)).sort((a,b)=>voteCount(b.id)-voteCount(a.id)||a.name.localeCompare(b.name,"zh-Hant"));const rankMap=new Map(rankedProducts.map((p,index)=>[p.id,index+1]));
  const isMyChoice=(productId:string)=>draftNominations.includes(productId)||myVotes.some(v=>v.product_id===productId);
  const comparePrice=(a:Product,b:Product,direction:1|-1)=>{if(a.reference_price==null&&b.reference_price==null)return a.name.localeCompare(b.name,"zh-Hant");if(a.reference_price==null)return 1;if(b.reference_price==null)return-1;return(a.reference_price-b.reference_price)*direction||a.name.localeCompare(b.name,"zh-Hant")};
  const compareProducts=(a:Product,b:Product)=>{const choiceOrder=Number(isMyChoice(b.id))-Number(isMyChoice(a.id));if(choiceOrder)return choiceOrder;if(sortMode==="votes")return voteCount(b.id)-voteCount(a.id)||a.name.localeCompare(b.name,"zh-Hant");if(sortMode==="name")return a.name.localeCompare(b.name,"zh-Hant");if(sortMode==="price-asc")return comparePrice(a,b,1);if(sortMode==="price-desc")return comparePrice(a,b,-1);return["voting","results","purchase"].includes(phase)?voteCount(b.id)-voteCount(a.id)||a.name.localeCompare(b.name,"zh-Hant"):a.category.localeCompare(b.category,"zh-Hant")||a.name.localeCompare(b.name,"zh-Hant")};
  const shown=products.filter(p=>(phase==="nomination"||phase==="upcoming"||nominatedProducts.has(p.id))&&(category==="全部"||p.category===category)&&`${p.brand}${p.name}${p.category}`.toLowerCase().includes(query.trim().toLowerCase())).sort(compareProducts);
  async function toggleNomination(product:Product){if(phase!=="nomination")return;const selected=draftNominations.includes(product.id);if(!selected&&draftNominations.length>=campaign!.nomination_limit)return notify(`最多提名 ${campaign!.nomination_limit} 項`);if(!selected){const others=nominations.filter(n=>n.product_id===product.id&&n.employee_id!==employee.id);if(others.length&&!await askConfirm({title:"這項商品已有人提名",items:[`${others.map(x=>x.nominator_name).join("、")} 已經提名這項商品。`,`共同提名後，會固定使用你的 1 票。`],confirmLabel:"仍要共同提名"}))return}const previousDraft=draftNominations;const previousNominations=nominations;const previousVotes=votes;const next=selected?draftNominations.filter(id=>id!==product.id):[...draftNominations,product.id];setDraftNominations(next);if(selected){setNominations(nominations.filter(n=>n.employee_id!==employee.id||n.product_id!==product.id));setVotes(votes.filter(v=>v.employee_id!==employee.id||v.product_id!==product.id||v.kind!=="nomination"))}else{const now=new Date().toISOString();setNominations([...nominations,{id:`optimistic-n-${product.id}`,campaign_id:campaign!.id,product_id:product.id,employee_id:employee.id,nominator_name:employee.name,created_at:now}]);setVotes([...votes,{id:`optimistic-v-${product.id}`,campaign_id:campaign!.id,product_id:product.id,employee_id:employee.id,voter_name:employee.name,kind:"nomination",created_at:now}])}const {error}=await supabase.rpc("set_nominations",{p_campaign_id:campaign!.id,p_product_ids:next});if(error){setDraftNominations(previousDraft);setNominations(previousNominations);setVotes(previousVotes);notify(error.message)}else{notify(selected?"已取消提名，名額與固定票已返還":"已加入提名並計入固定票");await load(true)}}
  async function toggleVote(product:Product){if(phase!=="voting")return;const fixed=myVotes.some(v=>v.product_id===product.id&&v.kind==="nomination");if(fixed)return notify("提名票已鎖定，投票階段不能取消");const regular=myVotes.filter(v=>v.kind==="regular").map(v=>v.product_id);const next=regular.includes(product.id)?regular.filter(id=>id!==product.id):[...regular,product.id];if(next.length+myVotes.filter(v=>v.kind==="nomination").length>campaign!.vote_limit)return notify(`本期最多 ${campaign!.vote_limit} 票`);const previous=votes;const otherVotes=votes.filter(v=>v.employee_id!==employee.id||v.kind!=="regular");const optimistic=next.map(productId=>({id:`optimistic-${productId}`,campaign_id:campaign!.id,product_id:productId,employee_id:employee.id,voter_name:employee.name,kind:"regular" as const,created_at:new Date().toISOString()}));setVotes([...otherVotes,...optimistic]);const {error}=await supabase.rpc("set_regular_votes",{p_campaign_id:campaign!.id,p_product_ids:next});if(error){setVotes(previous);notify(error.message)}else{notify(regular.includes(product.id)?"已取消這一票":"投票已更新");await load(true)}}
  async function addCustomProduct(e:FormEvent<HTMLFormElement>){e.preventDefault();if(draftNominations.length>=campaign!.nomination_limit)return notify(`已達提名上限 ${campaign!.nomination_limit} 項`);const form=new FormData(e.currentTarget);const file=form.get("image") instanceof File&&form.get("image") as File;try{const {data,error}=await supabase.rpc("add_custom_product_and_nominate",{p_campaign_id:campaign!.id,p_name:String(form.get("name")),p_category:String(form.get("category")),p_brand:String(form.get("brand")||""),p_size:String(form.get("size")||""),p_reference_price:form.get("reference_price")?Number(form.get("reference_price")):null,p_source_url:null});if(error)throw error;if(file&&file.size>0){const path=await uploadProductImage(file,employee.id);const attached=await supabase.rpc("set_product_image",{p_product_id:data,p_image_path:path});if(attached.error)throw attached.error}sessionStorage.removeItem("snack-vote-custom-product-draft");setCustomOpen(false);notify("商品已送審，並先計入你的提名與固定票");await load(true)}catch(error){const text=errorText(error);notify(text.startsWith("DUPLICATE_PRODUCT")?"商品庫已有相同品項，請直接提名既有商品":text)}}
  async function addComment(productId:string){const body=(commentDrafts[productId]??"").trim();if(!body)return;const previous=comments;const optimistic:Comment={id:`optimistic-${crypto.randomUUID()}`,campaign_id:campaign!.id,product_id:productId,employee_id:employee.id,author_name:employee.name,body,created_at:new Date().toISOString()};setComments([...comments,optimistic]);setCommentDrafts(x=>({...x,[productId]:""}));const {error}=await supabase.from("comments").insert({campaign_id:campaign!.id,product_id:productId,employee_id:employee.id,author_name:employee.name,body});if(error){setComments(previous);setCommentDrafts(x=>({...x,[productId]:body}));return notify(error.message)}await load(true)}
  const copy=phase==="nomination"?["商品提名中","把想吃的，放進本月候選單",`截止前可隨時更換；每項提名固定使用 1 票。`]:phase==="voting"?["具名投票中","本月零食，現在由大家決定",`你共有 ${campaign.vote_limit} 票；額外票可在截止前更換。`]:phase==="results"?["結果揭曉中","票數已鎖定，看看本月結果","排名與具名票數已公開。"]:phase==="upcoming"?["本期尚未開始","本月零食活動即將開始",`提名將於 ${shortDate(campaign.start_at)} 開放。`]:["安排採購中","本月採購清單整理中","管理者正依排名、預算與實際售價確認數量。"];
  return <ShellHeader employee={employee}><section className="hero"><div className="hero-main"><div className="eyebrow"><span className="live-dot"/>{copy[0]} · {campaign.label}</div><h1>{copy[1]}</h1><p>{copy[2]}</p><div className="quota-row"><div className="quota-card"><span>我的提名</span><strong>{draftNominations.length}<small>／{campaign.nomination_limit}</small></strong></div><div className="quota-card"><span>本期票數</span><strong>{myVotes.length}<small>／{campaign.vote_limit}</small></strong></div></div></div><Timeline campaign={campaign} phase={phase}/></section><section className="content-head"><div><p className="section-kicker">SNACK CATALOG</p><h2>{phase==="nomination"?"今天想提名哪一款？":"看看大家支持誰"}</h2></div>{phase==="nomination"&&<button className="custom-product-button" onClick={()=>setCustomOpen(x=>!x)}>＋ 找不到商品？自行新增</button>}</section>{customOpen&&<form className="custom-product-form" onSubmit={addCustomProduct}><div><strong>新增商品並提名</strong><small>送出後會先列為待審商品；若被退回，提名名額與固定票會自動返還。</small></div><input required name="name" placeholder="商品名稱"/><input name="brand" placeholder="品牌（選填）"/><select required name="category" defaultValue=""><option value="" disabled>選擇分類</option>{categories.slice(1).map(x=><option key={x}>{x}</option>)}</select><input name="size" placeholder="規格（選填）"/><input name="reference_price" type="number" min="0" placeholder="參考價（選填）"/><label className="image-input">商品圖<input name="image" type="file" accept="image/jpeg,image/png,image/webp,image/gif"/></label><button>送出並提名</button></form>}<div className="filters filters-with-sort"><label className="search"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜尋商品、品牌或分類"/></label><div className="category-list">{categories.map(c=><button key={c} className={c===category?"active":""} onClick={()=>setCategory(c)}>{c}</button>)}</div><label className="sort-control"><span>排序方式</span><select value={sortMode} onChange={e=>setSortMode(e.target.value as ProductSort)}><option value="smart">智慧排序</option><option value="votes">票數高到低</option><option value="name">商品名稱</option><option value="price-asc">價格低到高</option><option value="price-desc">價格高到低</option></select><small>我的提名／投票優先</small></label></div><section className="product-grid">{shown.map((p,index)=>{const ns=nominations.filter(n=>n.product_id===p.id);const vs=votes.filter(v=>v.product_id===p.id);const pcs=comments.filter(c=>c.product_id===p.id);const selected=draftNominations.includes(p.id);const voted=myVotes.some(v=>v.product_id===p.id);return <article className="product-card" key={p.id}><div className={`product-visual ${tones[index%tones.length]} ${p.image_path?"has-image":""}`}>{p.image_path?<img src={productImageUrl(p.image_path)} alt={`${p.brand} ${p.name}`}/>:<span>{icons[p.category]??"✦"}</span>}<small>{p.category}</small>{rankMap.has(p.id)&&["voting","results","purchase"].includes(phase)&&<b>第 {rankMap.get(p.id)} 名</b>}</div><div className="product-body"><div className="brand-line"><span>{p.brand}{p.approval_status==="pending"?" · 待管理者審核":""}</span><strong>{p.reference_price==null?"待確認":`參考 $${p.reference_price}`}</strong></div><h3>{p.name}</h3><p>{p.size}</p>{ns.length>0&&<div className="nominator"><span>{ns.map(n=>n.nominator_name).join("、")} 提名</span></div>}{["voting","results","purchase"].includes(phase)&&<div className="voter-line"><strong>第 {rankMap.get(p.id)} 名 · {vs.length} 票</strong><span>{vs.map(v=>v.voter_name).join("、")||"尚無投票"}</span></div>}<div className="card-actions">{phase==="nomination"?<button className={`primary-action ${selected?"selected":""}`} onClick={()=>toggleNomination(p)}>{selected?"✓ 已提名（可取消）":"＋ 納入本期"}</button>:phase==="voting"?<button className={`primary-action ${voted?"selected":""}`} onClick={()=>toggleVote(p)}>{voted?(myVotes.some(v=>v.product_id===p.id&&v.kind==="nomination")?"▣ 提名票":"✓ 已投票"):"投一票"}</button>:<span className="rank-label">第 {rankMap.get(p.id)} 名 · {vs.length} 票</span>}</div>{["nomination","voting"].includes(phase)&&<div className="comment-box"><div className="comment-list">{pcs.slice(-3).map(c=><p key={c.id}><strong>{c.author_name}</strong>{c.body}</p>)}{!pcs.length&&<small>還沒有人留言，來幫這款拉票吧。</small>}</div><div className="comment-compose"><input maxLength={500} value={commentDrafts[p.id]??""} onChange={e=>setCommentDrafts(x=>({...x,[p.id]:e.target.value}))} onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();void addComment(p.id)}}} placeholder="留言拉票…"/><button onClick={()=>addComment(p.id)}>送出</button></div></div>}</div></article>})}{!shown.length&&<div className="empty-campaign">目前沒有符合條件的商品。</div>}</section>{toast&&<div className="toast">{toast}</div>}{confirmElement}</ShellHeader>
}

function ShellHeader({employee,children}:{employee:Employee;children:React.ReactNode}){const shared=getSessionMode()==="shared";return <main className="employee-shell"><header className="topbar"><div className="brand"><span className="brand-mark">S</span><div><strong>Snack Vote</strong><small>公司零食共選</small></div></div><div className="top-actions"><TextSizeControl/><span className={`session-mode ${getSessionMode()}`}>{shared?"共用電腦模式":"此瀏覽器已登入"}</span>{employee.role==="admin"&&<a href="#/admin">管理後台</a>}<button onClick={()=>supabase.auth.signOut()}>登出</button><div className="profile"><span className="avatar">{employee.name.slice(0,1)}</span><div><strong>{employee.name}</strong><small>{employee.email}{shared?" · 閒置 30 分鐘自動登出":""}</small></div></div></div></header>{children}<footer>商品與價格僅供採購參考，實際售價及庫存以門市為準。</footer></main>}

function Timeline({campaign,phase}:{campaign:Campaign;phase:Phase}){const index={upcoming:-1,nomination:0,voting:1,results:2,purchase:3}[phase];const items=[["開始",campaign.start_at],["提名截止",campaign.nomination_deadline],["投票截止",campaign.voting_deadline],["安排採購",campaign.purchase_at]];return <div className="timeline-panel"><div className="milestone-row">{items.map((x,i)=><div key={x[0]} className={`milestone ${i<=index?"done":""} ${i===index?"current":""}`}><span>{i+1}</span><strong>{x[0]}</strong><small>{shortDate(x[1])}</small></div>)}</div><div className="period-row"><div className={`period ${phase==="nomination"?"active":""}`}><strong>提名階段</strong><small>{shortDate(campaign.start_at)}–{shortDate(campaign.nomination_deadline)}</small></div><div className={`period ${phase==="voting"?"active":""}`}><strong>投票階段</strong><small>{shortDate(campaign.nomination_deadline)}–{shortDate(campaign.voting_deadline)}</small></div><div className={`period ${phase==="results"?"active":""}`}><strong>結果揭曉階段</strong><small>{shortDate(campaign.voting_deadline)}–{shortDate(campaign.purchase_at)}</small></div></div></div>}

type AdminTab="overview"|"campaign"|"employees"|"locations"|"products"|"pending"|"purchase"|"history";
const adminTabs:{id:AdminTab;icon:string;label:string}[]=[{id:"overview",icon:"⌂",label:"管理總覽"},{id:"campaign",icon:"◫",label:"活動管理"},{id:"employees",icon:"◎",label:"員工名單"},{id:"locations",icon:"⌖",label:"上班地點"},{id:"products",icon:"▦",label:"商品資料庫"},{id:"pending",icon:"◇",label:"待審商品"},{id:"purchase",icon:"✓",label:"採購清單"},{id:"history",icon:"↺",label:"歷史紀錄"}];

function AdminApp({employee}:{employee:Employee}){
  const {ask:askConfirm,element:confirmElement}=useConfirmDialog();
  const [tab,setTab]=useState<AdminTab>("overview");const [employees,setEmployees]=useState<Employee[]>([]);const [workLocations,setWorkLocations]=useState<WorkLocation[]>([]);const [campaigns,setCampaigns]=useState<Campaign[]>([]);const [selectedCampaignId,setSelectedCampaignId]=useState<string|null>(null);const [editingCampaign,setEditingCampaign]=useState<Campaign|null>(null);const [members,setMembers]=useState<CampaignMember[]>([]);const [products,setProducts]=useState<Product[]>([]);const [productCategories,setProductCategories]=useState<ProductCategory[]>([]);const [nominations,setNominations]=useState<Nomination[]>([]);const [votes,setVotes]=useState<Vote[]>([]);const [comments,setComments]=useState<Comment[]>([]);const [purchases,setPurchases]=useState<PurchaseItem[]>([]);const [name,setName]=useState("");const [email,setEmail]=useState("");const [employeeLocation,setEmployeeLocation]=useState("");const [message,setMessage]=useState("");const [busy,setBusy]=useState(false);const [emailingEmployeeId,setEmailingEmployeeId]=useState<string|null>(null);const [sentEmployeeIds,setSentEmployeeIds]=useState<Set<string>>(()=>new Set());const [newCampaign,setNewCampaign]=useState(false);const [editingProduct,setEditingProduct]=useState<Product|null>(null);
  const now=Date.now();const latest=campaigns.find(c=>c.id===selectedCampaignId)??campaigns.find(c=>c.status==="active"&&+new Date(c.start_at)<=now)??campaigns.find(c=>c.status==="active")??campaigns[0]??null;const campaignForForm=editingCampaign??latest;const catalogProducts=products.filter(p=>!p.deleted_at);const pending=catalogProducts.filter(p=>p.approval_status==="pending");
  const load=useCallback(async()=>{const [{data:e},{data:l},{data:c},{data:m},{data:p},{data:ca},{data:n},{data:v},{data:co},{data:pi}]=await Promise.all([supabase.from("employees").select("id,user_id,name,email,role,active,work_location_id").order("name"),supabase.from("work_locations").select("id,name,active").order("name"),supabase.from("campaigns").select("*").order("start_at",{ascending:false}),supabase.from("campaign_members").select("*").order("name_snapshot"),supabase.from("products").select("*").order("category"),supabase.from("product_categories").select("id,name,sort_order").order("sort_order").order("name"),supabase.from("nominations").select("*").order("created_at"),supabase.from("votes").select("*").order("created_at"),supabase.from("comments").select("*").is("deleted_at",null).order("created_at"),supabase.from("purchase_items").select("*").order("rank")]);setEmployees((e??[]) as Employee[]);setWorkLocations((l??[]) as WorkLocation[]);setCampaigns((c??[]) as Campaign[]);setMembers((m??[]) as CampaignMember[]);setProducts((p??[]) as Product[]);setProductCategories((ca??[]) as ProductCategory[]);setNominations((n??[]) as Nomination[]);setVotes((v??[]) as Vote[]);setComments((co??[]) as Comment[]);setPurchases((pi??[]) as PurchaseItem[])},[]);useEffect(()=>{void load()},[load]);
  useEffect(()=>{if(tab!=="products")return;const form=document.querySelector<HTMLFormElement>("form.product-form-with-image");if(!form)return;const draft=readFormDraft("snack-vote-admin-product-draft");Object.entries(draft).forEach(([name,value])=>{const field=form.elements.namedItem(name);if(field instanceof HTMLInputElement||field instanceof HTMLSelectElement){if(field.type!=="file")field.value=value}});const save=()=>saveFormDraft("snack-vote-admin-product-draft",form);form.addEventListener("input",save);form.addEventListener("change",save);return()=>{form.removeEventListener("input",save);form.removeEventListener("change",save)}},[tab]);
  function flash(text:string){setMessage(text);window.setTimeout(()=>setMessage(""),3500)}
  async function addEmployee(e:FormEvent){e.preventDefault();if(!employeeLocation)return flash("請選擇上班地點");setBusy(true);const {error}=await supabase.from("employees").insert({name:name.trim(),email:email.trim().toLowerCase(),role:"employee",work_location_id:employeeLocation});setBusy(false);if(error)return flash(error.message);setName("");setEmail("");flash("員工已新增，可請對方使用 Email 驗證碼登入");await load()}
  async function sendLoginEmail(row:Employee){if(!row.active)return flash("請先重新啟用這位員工，再寄送驗證碼");setEmailingEmployeeId(row.id);const {error}=await supabase.auth.signInWithOtp({email:row.email,options:{shouldCreateUser:true}});setEmailingEmployeeId(null);if(error)return flash(error.message.includes("rate limit")?"寄信次數過於頻繁，請稍後再試":error.message);setSentEmployeeIds(previous=>new Set(previous).add(row.id));flash(`已寄送登入驗證碼給 ${row.name}`)}
  async function revokeEmployeeSessions(row:Employee){if(!row.user_id)return flash("這位員工尚未登入過，沒有可撤銷的工作階段");if(row.id===employee.id)return flash("不能從這裡撤銷目前登入的管理者工作階段");if(!await askConfirm({title:`要求 ${row.name} 重新登入？`,items:["此帳號在其他電腦與瀏覽器的登入工作階段都會失效。","員工下次使用時必須重新收取 Email 驗證碼登入。"],confirmLabel:"撤銷所有登入",danger:true}))return;setBusy(true);const {error}=await supabase.functions.invoke("revoke-user-session",{body:{employeeId:row.id}});setBusy(false);if(error)return flash(`撤銷失敗：${error.message}`);flash(`${row.name} 的登入工作階段已全部撤銷`)}
  async function updateEmployee(row:Employee,patch:Partial<Employee>){if(row.id===employee.id&&patch.active===false)return flash("不能停用目前登入的管理者");const {error}=await supabase.from("employees").update(patch).eq("id",row.id);if(error)flash(error.message);else await load()}
  async function addLocation(locationName:string){const clean=locationName.trim();if(!clean)return;const {error}=await supabase.from("work_locations").insert({name:clean});if(error)return flash(error.code==="23505"?"已有同名地點":error.message);flash(`已新增「${clean}」`);await load()}
  async function renameLocation(row:WorkLocation,newName:string){const clean=newName.trim();if(!clean||clean===row.name)return;const {error}=await supabase.from("work_locations").update({name:clean}).eq("id",row.id);if(error)return flash(error.code==="23505"?"已有同名地點":error.message);flash("上班地點已更新");await load()}
  async function deleteLocation(row:WorkLocation){if(!await askConfirm({title:`刪除「${row.name}」？`,items:["只有未分配員工、且沒有活動紀錄的地點可以刪除。"],confirmLabel:"確認刪除",danger:true}))return;const {error}=await supabase.rpc("delete_work_location",{p_location_id:row.id});if(error)return flash(error.message.includes("LOCATION_HAS_EMPLOYEES")?"仍有員工屬於此地點，請先調整員工地點":error.message.includes("LOCATION_HAS_CAMPAIGNS")?"此地點已有活動紀錄，因此不可刪除；可改為停用":error.message);flash("上班地點已刪除");await load()}
  async function toggleLocation(row:WorkLocation){const {error}=await supabase.from("work_locations").update({active:!row.active}).eq("id",row.id);if(error)return flash(error.message);flash(row.active?"上班地點已停用；既有活動與員工資料仍保留":"上班地點已重新啟用");await load()}
  async function saveCampaign(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);const id=String(form.get("id")||"");const wasNew=!id;const previous=campaigns.find(c=>c.id===id);const baseBudget=Number(form.get("budget"));const workLocationId=String(form.get("work_location_id")||"");const locationChanged=Boolean(previous&&previous.work_location_id!==workLocationId);const carryoverEnabled=form.get("carryover_enabled")==="true";const retainUnusedBudget=form.get("retain_unused_budget")==="true";const nominationLimit=Number(form.get("nomination_limit"));const voteLimit=Number(form.get("vote_limit"));if(!workLocationId)return flash("請選擇活動地點");if(!Number.isSafeInteger(baseBudget)||baseBudget<0)return flash("預算必須是 0 以上的整數");if(!Number.isInteger(nominationLimit)||!Number.isInteger(voteLimit)||nominationLimit<1||voteLimit<nominationLimit)return flash("總票數不可少於提名上限");const startAt=new Date(String(form.get("start_at"))).toISOString();let carryoverAmount=0;let carryoverFrom:string|null=null;let carryoverLabel="";let carryoverAvailable=true;if(carryoverEnabled){const carry=await supabase.rpc("calculate_campaign_carryover",{p_start_at:startAt,p_work_location_id:workLocationId,p_exclude_campaign_id:id||null});if(carry.error)return flash(carry.error.message);const detail=carry.data as {campaign_id:string|null;label:string|null;remaining:number;retained:boolean};carryoverAmount=Number(detail.remaining)||0;carryoverFrom=detail.campaign_id;carryoverLabel=detail.label??"";carryoverAvailable=detail.retained}const totalBudget=baseBudget+carryoverAmount;const useBreakdown=carryoverEnabled?(carryoverAvailable?`基本預算 NT$ ${baseBudget.toLocaleString()}＋${carryoverLabel||"同地點上期"}保留款 NT$ ${carryoverAmount.toLocaleString()}＝可用 NT$ ${totalBudget.toLocaleString()}`:`已選擇使用同地點上期保留款，但${carryoverLabel||"上一期"}未選擇保留，因此本期沒有結轉金額`):`本期不使用上期保留款，可用 NT$ ${baseBudget.toLocaleString()}`;const retainBreakdown=retainUnusedBudget?"本期未用餘額會保留給同地點下一期":"本期未用餘額不保留";const locationBreakdown=locationChanged?"活動地點變更後，參與名單會依新地點重新整理；既有提名、投票、留言與採購紀錄不會刪除。":null;if(!await askConfirm({title:`確認${wasNew?"新一期":"活動"}設定`,items:[useBreakdown,retainBreakdown,...(locationBreakdown?[locationBreakdown]:[])],confirmLabel:"確認並儲存"}))return;setBusy(true);const payload={label:String(form.get("label")),budget:totalBudget,base_budget:baseBudget,carryover_enabled:carryoverEnabled,retain_unused_budget:retainUnusedBudget,carryover_amount:carryoverAmount,carryover_from:carryoverFrom,work_location_id:workLocationId,nomination_limit:nominationLimit,vote_limit:voteLimit,start_at:startAt,nomination_deadline:new Date(String(form.get("nomination_deadline"))).toISOString(),voting_deadline:new Date(String(form.get("voting_deadline"))).toISOString(),purchase_at:new Date(String(form.get("purchase_at"))).toISOString(),status:String(form.get("status")),created_by:employee.id};const result=id?await supabase.from("campaigns").update(payload).eq("id",id).select("id").single():await supabase.from("campaigns").insert(payload).select("id").single();if(result.error){setBusy(false);return flash(result.error.message)}const savedId=result.data.id;if(wasNew||locationChanged){const snap=await supabase.rpc("snapshot_active_employees",{p_campaign_id:savedId});if(snap.error){setBusy(false);return flash(snap.error.message)}}setBusy(false);setNewCampaign(false);setEditingCampaign(null);setSelectedCampaignId(savedId);flash(`活動設定已更新；可用預算為 NT$ ${totalBudget.toLocaleString()}${locationChanged?"，參與名單已依新地點重整":""}`);await load()}
  async function addProduct(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const form=new FormData(e.currentTarget);try{const image=form.get("image");const imagePath=image instanceof File&&image.size>0?await uploadProductImage(image,employee.id):null;const payload={brand:String(form.get("brand")).trim(),name:String(form.get("name")).trim(),category:String(form.get("category")).trim(),size:String(form.get("size")).trim(),reference_price:form.get("reference_price")?Number(form.get("reference_price")):null,image_path:imagePath,origin:"catalog",approval_status:"approved",active:true};const {error}=await supabase.from("products").insert(payload);if(error)throw error;sessionStorage.removeItem("snack-vote-admin-product-draft");e.currentTarget.reset();flash("商品已加入資料庫");await load()}catch(error){flash(errorText(error))}finally{setBusy(false)}}
  async function addStarterProducts(){const existing=new Set(products.filter(p=>p.active).map(p=>`${p.brand.trim().toLowerCase()}|${p.name.trim().toLowerCase()}|${p.size.trim().toLowerCase()}`));const rows=starterProducts.filter(([brand,name,,size])=>!existing.has(`${brand.toLowerCase()}|${name.toLowerCase()}|${size.toLowerCase()}`)).map(([brand,name,category,size])=>({brand,name,category,size,reference_price:null,source_url:null,origin:"catalog",approval_status:"approved",active:true}));if(!rows.length)return flash("基礎商品都已經在資料庫中");if(!await askConfirm({title:"加入基礎商品",items:[`將加入 ${rows.length} 項基礎商品。`,`價格會先標示為待確認，可再逐項補充。`],confirmLabel:"確認加入"}))return;setBusy(true);const existingCategories=new Set(productCategories.map(c=>c.name));const missingCategories=[...new Set(rows.map(r=>r.category))].filter(category=>!existingCategories.has(category));if(missingCategories.length){const categoryResult=await supabase.from("product_categories").insert(missingCategories.map((category,index)=>({name:category,sort_order:(productCategories.at(-1)?.sort_order??0)+(index+1)*10})));if(categoryResult.error){setBusy(false);return flash(categoryResult.error.message)}}const {error}=await supabase.from("products").insert(rows);setBusy(false);if(error)return flash(error.message);flash(`已加入 ${rows.length} 項基礎商品`);await load()}
  async function addCategory(categoryName:string){const clean=categoryName.trim();if(!clean)return;setBusy(true);const nextOrder=(productCategories.at(-1)?.sort_order??0)+10;const {error}=await supabase.from("product_categories").insert({name:clean,sort_order:nextOrder});setBusy(false);if(error)return flash(error.code==="23505"?"已有同名類別":error.message);flash(`已新增「${clean}」類別`);await load()}
  async function renameCategory(row:ProductCategory,newName:string){const clean=newName.trim();if(!clean||clean===row.name)return;setBusy(true);const {error}=await supabase.rpc("rename_product_category",{p_category_id:row.id,p_new_name:clean});setBusy(false);if(error)return flash(error.message.includes("CATEGORY_ALREADY_EXISTS")?"已有同名類別":error.message);flash(`類別已改名為「${clean}」，相關商品已同步更新`);await load()}
  async function deleteCategory(row:ProductCategory){const related=catalogProducts.filter(p=>p.category===row.name);const relatedIds=new Set(related.map(p=>p.id));const activeCampaignIds=new Set(campaigns.filter(c=>c.status==="active").map(c=>c.id));const used=[...nominations,...votes].some(x=>activeCampaignIds.has(x.campaign_id)&&relatedIds.has(x.product_id));if(used)return flash("此類別的商品已在進行中的活動被提名或投票，因此不可刪除");const warning=related.length?`刪除「${row.name}」會一併刪除其中 ${related.length} 項商品。過往活動紀錄仍會保留。確定刪除嗎？`:`確定刪除空白類別「${row.name}」嗎？`;if(!await askConfirm({title:`刪除「${row.name}」類別`,items:[warning.replace("確定刪除嗎？","").replace(`確定刪除空白類別「${row.name}」嗎？`,`這個類別目前沒有商品。`)],confirmLabel:"確認刪除",danger:true}))return;setBusy(true);const {data,error}=await supabase.rpc("delete_product_category",{p_category_id:row.id});setBusy(false);if(error)return flash(error.message.includes("CATEGORY_IN_USE_CURRENT_CAMPAIGN")?"此類別的商品已在進行中的活動被提名或投票，因此不可刪除":error.message);flash(`已刪除「${row.name}」與 ${data??related.length} 項商品`);await load()}
  async function updateProduct(id:string,patch:Record<string,unknown>,success:string){const {error}=await supabase.from("products").update(patch).eq("id",id);if(error)flash(error.message);else{flash(success);await load()}}
  async function replaceProductImage(product:Product,file:File){try{setBusy(true);const path=await uploadProductImage(file,employee.id);const {error}=await supabase.rpc("set_product_image",{p_product_id:product.id,p_image_path:path});if(error)throw error;flash("商品圖片已更新");await load()}catch(error){flash(errorText(error))}finally{setBusy(false)}}
  async function reviewProduct(product:Product,decision:"approved"|"rejected"){if(decision==="rejected"&&!await askConfirm({title:`退回「${product.name}」`,items:[`相關提名與固定票會立即移除。`,`受影響同仁的提名名額與票數會自動返還。`],confirmLabel:"確認退回",danger:true}))return;const {data,error}=await supabase.rpc("review_product",{p_product_id:product.id,p_decision:decision});if(error)return flash(error.message);flash(decision==="approved"?"商品已核准並加入商品庫":`商品已退回，已返還 ${data??0} 筆提名與固定票`);await load()}
  function editProduct(product:Product){setEditingProduct(product)}
  async function saveEditedProduct(form:FormData,image:File|null){if(!editingProduct)return;try{setBusy(true);let imagePath=editingProduct.image_path;if(image){imagePath=await uploadProductImage(image,employee.id)}const payload={brand:String(form.get("brand")||"").trim(),name:String(form.get("name")||"").trim(),category:String(form.get("category")||"").trim(),size:String(form.get("size")||"").trim(),reference_price:form.get("reference_price")?Number(form.get("reference_price")):null,image_path:imagePath,active:String(form.get("active"))==="true"};const {error}=await supabase.from("products").update(payload).eq("id",editingProduct.id);if(error)throw error;setEditingProduct(null);flash("商品資料已完整更新");await load()}catch(error){flash(errorText(error))}finally{setBusy(false)}}
  async function generatePurchase(){if(!latest)return flash("請先建立活動");setBusy(true);const {data,error}=await supabase.rpc("generate_purchase_plan",{p_campaign_id:latest.id});setBusy(false);if(error)return flash(error.message);const result=data as {remaining:number;missing_prices:number};flash(result.missing_prices?`清單已產生；${result.missing_prices} 項尚未設定價格，因此未配置數量`:`清單已產生，預算餘額 NT$ ${Number(result.remaining).toLocaleString()}`);await load()}
  async function updatePurchase(row:PurchaseItem,patch:Partial<PurchaseItem>){const {error}=await supabase.from("purchase_items").update(patch).eq("id",row.id);if(error)flash(error.message);else await load()}
  async function toggleCampaignMember(row:Employee){if(!latest)return;const current=members.find(m=>m.campaign_id===latest.id&&m.employee_id===row.id);const active=!(current?.active??false);const result=current?await supabase.from("campaign_members").update({active}).eq("id",current.id):await supabase.from("campaign_members").insert({campaign_id:latest.id,employee_id:row.id,name_snapshot:row.name,email_snapshot:row.email,active});if(result.error)flash(result.error.message);else{flash(active?`${row.name} 已加入本期`:`${row.name} 已從本期排除`);await load()}}
  async function forceDeleteCampaign(row:Campaign){const nominationCount=nominations.filter(x=>x.campaign_id===row.id).length;const voteCount=votes.filter(x=>x.campaign_id===row.id).length;const commentCount=comments.filter(x=>x.campaign_id===row.id).length;const purchaseCount=purchases.filter(x=>x.campaign_id===row.id).length;if(!await askConfirm({title:`強制刪除「${row.label}」？`,items:[`將永久刪除 ${nominationCount} 筆提名、${voteCount} 票、${commentCount} 則留言與 ${purchaseCount} 筆採購項目。`,`活動參與名單、寄信紀錄也會一併刪除；商品與員工資料不受影響。`],confirmLabel:"繼續確認",danger:true}))return;if(!await askConfirm({title:"最後確認：此操作無法復原",items:[`確定永久刪除「${row.label}」？`,`若只是暫時不顯示，應改為封存而不是刪除。`],confirmLabel:"永久刪除活動",danger:true}))return;setBusy(true);const {error}=await supabase.rpc("force_delete_campaign",{p_campaign_id:row.id,p_expected_label:row.label});setBusy(false);if(error)return flash(error.message.includes("CAMPAIGN_LABEL_MISMATCH")?"活動名稱驗證失敗，請重新整理後再試":error.message);if(selectedCampaignId===row.id)setSelectedCampaignId(null);if(editingCampaign?.id===row.id)setEditingCampaign(null);flash(`已永久刪除「${row.label}」及其活動資料`);await load()}
  const title=adminTabs.find(x=>x.id===tab)?.label??"管理總覽";
  return <main className="admin-shell"><aside className="admin-nav"><div className="brand admin-brand"><span className="brand-mark">S</span><div><strong>Snack Vote</strong><small>管理後台</small></div></div><nav>{adminTabs.map(item=><button key={item.id} className={tab===item.id?"active":""} onClick={()=>setTab(item.id)}><span>{item.icon}</span>{item.label}{item.id==="pending"&&pending.length>0&&<b className="nav-badge">{pending.length}</b>}</button>)}<a href="#/"><button><span>←</span>回員工頁面</button></a></nav><div className="admin-user"><span className="avatar">{employee.name.slice(0,1)}</span><div><strong>{employee.name}</strong><small>系統管理者</small></div></div></aside><section className="admin-main"><header className="admin-top"><div><p className="section-kicker">ADMIN CONSOLE</p><h1>{title}</h1></div><div className="admin-status"><TextSizeControl/><span className={`session-mode ${getSessionMode()}`}>{getSessionMode()==="shared"?"共用電腦模式":"此瀏覽器已登入"}</span>{latest&&<span className={`status-pill ${phaseOf(latest)}`}>{latest.label} · {phaseLabel(phaseOf(latest))}</span>}<button className="table-action" onClick={()=>supabase.auth.signOut()}>登出</button></div></header>{message&&<div className="admin-toast">{message}</div>}<div className="admin-content">
    {tab==="overview"&&<><div className="stat-grid"><article><span>啟用員工</span><strong>{employees.filter(e=>e.active).length}</strong><small>人</small></article><article><span>活動紀錄</span><strong>{campaigns.length}</strong><small>期</small></article><article><span>啟用商品</span><strong>{catalogProducts.filter(p=>p.active&&p.approval_status==="approved").length}</strong><small>項</small></article><article><span>待審商品</span><strong>{pending.length}</strong><small>項</small></article></div><div className="admin-two"><section className="admin-card"><div className="card-title"><div><p className="section-kicker">CURRENT CAMPAIGN</p><h2>{latest?.label??"尚未建立本期活動"}</h2></div>{latest&&<button onClick={()=>setTab("campaign")}>編輯設定 →</button>}</div>{latest?<><Timeline campaign={latest} phase={phaseOf(latest)}/><div className="rule-note"><strong>本期規則</strong><span>預算 NT$ {Number(latest.budget).toLocaleString()} · 每人提名 {latest.nomination_limit} 項 · 共 {latest.vote_limit} 票</span></div></>:<div className="admin-empty"><button className="solid-button" onClick={()=>setTab("campaign")}>建立第一期活動</button></div>}</section><section className="admin-card"><div className="card-title"><div><p className="section-kicker">QUICK ACTIONS</p><h2>接下來要處理</h2></div></div><div className="quick-list"><button onClick={()=>setTab("pending")}><strong>{pending.length}</strong><span>筆待審商品</span><em>前往審核 →</em></button><button onClick={()=>setTab("purchase")}><strong>{latest?votes.filter(v=>v.campaign_id===latest.id).length:0}</strong><span>張本期票數</span><em>安排採購 →</em></button><button onClick={()=>setTab("employees")}><strong>{employees.filter(e=>e.active).length}</strong><span>位啟用員工</span><em>管理名單 →</em></button></div></section></div></>}
    {tab==="campaign"&&<><div className="section-actions"><div><p>{newCampaign?"設定新一期活動；既有活動會保留在歷史紀錄。":"目前顯示啟用中的本期活動；此處金額與採購清單使用同一筆資料。"}</p>{!newCampaign&&<select className="campaign-switch" value={campaignForForm?.id??""} onChange={e=>{setSelectedCampaignId(e.target.value);setEditingCampaign(null)}}>{campaigns.map(c=><option key={c.id} value={c.id}>{workLocations.find(l=>l.id===c.work_location_id)?.name??"未分類"}｜{c.label}</option>)}</select>}</div><button className="solid-button" onClick={()=>{setNewCampaign(x=>!x);setEditingCampaign(null)}}>{newCampaign?"取消建立新活動":"＋ 建立下一期"}</button></div><CampaignForm key={newCampaign?"new":campaignForForm?`${campaignForForm.id}:${campaignForForm.base_budget}:${campaignForForm.carryover_enabled}:${campaignForForm.retain_unused_budget}:${campaignForForm.carryover_amount}:${campaignForForm.budget}:${campaignForForm.start_at}:${campaignForForm.nomination_deadline}:${campaignForForm.voting_deadline}:${campaignForForm.purchase_at}:${campaignForForm.nomination_limit}:${campaignForForm.vote_limit}:${campaignForForm.status}`:"empty"} campaign={newCampaign?null:campaignForForm} locations={workLocations} busy={busy} onSubmit={saveCampaign}/>{!newCampaign&&campaignForForm&&<CampaignMemberPanel campaign={campaignForForm} employees={employees} members={members} onToggle={toggleCampaignMember}/>}</>}
    {tab==="employees"&&<section className="admin-card"><div className="card-title"><div><p className="section-kicker">EMPLOYEE ROSTER</p><h2>員工名單</h2></div><span className="count-tag">{employees.length} 人</span></div><form className="add-employee" onSubmit={addEmployee}><input required placeholder="姓名" value={name} onChange={e=>setName(e.target.value)}/><input required type="email" placeholder="公司 Email" value={email} onChange={e=>setEmail(e.target.value)}/><select required value={employeeLocation} onChange={e=>setEmployeeLocation(e.target.value)}><option value="" disabled>選擇上班地點</option>{workLocations.filter(x=>x.active).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><button disabled={busy}>＋ 新增員工</button></form><div className="table-wrap"><table><thead><tr><th>姓名</th><th>Email</th><th>上班地點</th><th>權限</th><th>名單狀態</th><th>登入狀態</th><th>操作</th></tr></thead><tbody>{employees.map(row=><tr key={row.id}><td><strong>{row.name}</strong></td><td>{row.email}</td><td><select value={row.work_location_id} onChange={e=>updateEmployee(row,{work_location_id:e.target.value})}>{workLocations.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></td><td><select value={row.role} onChange={e=>updateEmployee(row,{role:e.target.value as Employee["role"]})}><option value="employee">員工</option><option value="admin">管理者</option></select></td><td><span className={row.active?"active-dot":"inactive-dot"}>{row.active?"啟用":"停用"}</span></td><td><span className={row.user_id?"login-ready":"login-pending"}>{row.user_id?"已登入過":"尚未登入"}</span></td><td><div className="employee-actions"><button className="table-action" onClick={()=>updateEmployee(row,{active:!row.active})}>{row.active?"停用":"重新啟用"}</button><button className="table-action email-action" disabled={!row.active||emailingEmployeeId===row.id||sentEmployeeIds.has(row.id)} onClick={()=>sendLoginEmail(row)}>{emailingEmployeeId===row.id?"寄送中…":sentEmployeeIds.has(row.id)?"✓ 已寄送":row.user_id?"寄送登入信":"寄送首次登入信"}</button></div></td></tr>)}</tbody></table></div></section>}
    {tab==="locations"&&<WorkLocationManager locations={workLocations} employees={employees} campaigns={campaigns} onAdd={addLocation} onRename={renameLocation} onDelete={deleteLocation} onToggle={toggleLocation}/>} 
    {tab==="products"&&<><CategoryManager categories={productCategories} products={catalogProducts} nominations={nominations} votes={votes} currentCampaigns={campaigns.filter(c=>c.status==="active")} busy={busy} onAdd={addCategory} onRename={renameCategory} onDelete={deleteCategory}/><section className="admin-card"><div className="card-title"><div><p className="section-kicker">ADD PRODUCT</p><h2>新增商品</h2></div><button className="seed-button" disabled={busy} onClick={addStarterProducts}>一鍵加入 39 項基礎商品</button></div><form className="product-form product-form-with-image" onSubmit={addProduct}><input name="brand" placeholder="品牌（可空白）"/><input required name="name" placeholder="商品名稱"/><select required name="category" defaultValue=""><option value="" disabled>選擇分類</option>{productCategories.map(c=><option key={c.id} value={c.name}>{c.name}</option>)}</select><input name="size" placeholder="規格，例如 100g"/><input name="reference_price" type="number" min="0" step="1" placeholder="參考價格"/><label className="compact-file">選擇商品圖<input name="image" type="file" accept="image/jpeg,image/png,image/webp,image/gif"/></label><button disabled={busy}>＋ 加入商品庫</button></form><div className="seed-note">圖片支援 JPG、PNG、WebP、GIF，單張上限 5MB。價格、包裝與庫存仍以實際門市為準。</div></section><section className="admin-card"><div className="card-title"><div><p className="section-kicker">PRODUCT CATALOG</p><h2>商品資料庫</h2></div><span className="count-tag">{catalogProducts.length} 項</span></div><div className="table-wrap"><table><thead><tr><th>圖片</th><th>商品</th><th>分類</th><th>參考價</th><th>來源</th><th>狀態</th><th>操作</th></tr></thead><tbody>{catalogProducts.filter(p=>p.approval_status!=="pending").map(p=><tr key={p.id}><td>{p.image_path?<img className="product-thumb" src={productImageUrl(p.image_path)} alt=""/>:<span className="thumb-placeholder">{icons[p.category]??"✦"}</span>}</td><td><strong>{p.brand} {p.name}</strong><small className="cell-sub">{p.size||"未填規格"}</small></td><td>{p.category}</td><td>{p.reference_price==null?"待確認":`NT$ ${p.reference_price}`}</td><td>{p.origin==="employee"?"同仁新增":"商品庫"}</td><td><span className={p.active?"active-dot":"inactive-dot"}>{p.active?"啟用":"停用"}</span></td><td><button className="table-action" onClick={()=>editProduct(p)}>修改</button><label className="table-upload">換圖<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" onChange={e=>{const file=e.target.files?.[0];if(file)void replaceProductImage(p,file)}}/></label><button className="table-action" onClick={()=>updateProduct(p.id,{active:!p.active},p.active?"商品已停用":"商品已重新啟用")}>{p.active?"停用":"啟用"}</button></td></tr>)}</tbody></table></div></section></>}
    {tab==="pending"&&<section className="admin-card"><div className="card-title"><div><p className="section-kicker">PRODUCT REVIEW</p><h2>同仁新增商品審核</h2></div><span className="count-tag">{pending.length} 項</span></div>{pending.length?<div className="review-grid">{pending.map(p=><article key={p.id}>{p.image_path?<img className="review-image" src={productImageUrl(p.image_path)} alt={p.name}/>:<div className="review-icon">{icons[p.category]??"✦"}</div>}<div><span>{p.category} · {p.brand||"未填品牌"}</span><h3>{p.name}</h3><p>{p.size||"未填規格"} · {p.reference_price==null?"價格待確認":`參考 NT$ ${p.reference_price}`}</p></div><div className="review-actions"><button className="approve" onClick={()=>reviewProduct(p,"approved")}>核准</button><button onClick={()=>reviewProduct(p,"rejected")}>退回並返還票數</button></div></article>)}</div>:<div className="admin-empty">目前沒有待審商品。</div>}</section>}
    {tab==="purchase"&&<PurchasePanel campaign={latest} products={products} purchases={purchases} onGenerate={generatePurchase} onUpdate={updatePurchase}/>} 
    {tab==="history"&&<HistoryPanel campaigns={campaigns} locations={workLocations} products={products} nominations={nominations} votes={votes} comments={comments} purchases={purchases} onEdit={campaign=>{setEditingCampaign(campaign);setSelectedCampaignId(campaign.id);setNewCampaign(false);setTab("campaign")}} onDelete={forceDeleteCampaign}/>} 
  </div></section>{editingProduct&&<ProductEditor product={editingProduct} categories={productCategories} busy={busy} onClose={()=>setEditingProduct(null)} onSave={saveEditedProduct}/>} {confirmElement}</main>
}

function phaseLabel(phase:Phase){return({upcoming:"尚未開始",nomination:"提名階段",voting:"投票階段",results:"結果揭曉",purchase:"安排採購"})[phase]}
function CampaignForm({campaign,locations,busy,onSubmit}:{campaign:Campaign|null;locations:WorkLocation[];busy:boolean;onSubmit:(e:FormEvent<HTMLFormElement>)=>void}){const [retainUnused,setRetainUnused]=useState(campaign?.retain_unused_budget??false);const [usePrevious,setUsePrevious]=useState(campaign?.carryover_enabled??false);const base=new Date();const defaults={start:new Date(base.getTime()+86400000),nomination:new Date(base.getTime()+8*86400000),voting:new Date(base.getTime()+15*86400000),purchase:new Date(base.getTime()+18*86400000)};return <section className="admin-card form-card"><div className="card-title"><div><p className="section-kicker">CAMPAIGN SETTINGS</p><h2>{campaign?"編輯本期活動":"建立本期活動"}</h2></div>{campaign&&<span className={`status-pill ${phaseOf(campaign)}`}>{phaseLabel(phaseOf(campaign))}</span>}</div><form onSubmit={onSubmit}><input type="hidden" name="id" value={campaign?.id??""}/><div className="form-grid"><label><span>活動名稱</span><input required name="label" defaultValue={campaign?.label??`${base.getFullYear()} 年 ${base.getMonth()+2} 月零食共選`} /></label><label><span>活動地點</span><select required name="work_location_id" defaultValue={campaign?.work_location_id??locations.find(x=>x.active)?.id??""}><option value="" disabled>選擇上班地點</option>{locations.filter(x=>x.active||x.id===campaign?.work_location_id).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><small>建立後只會納入此地點的啟用員工</small></label><label><span>每期預算金額</span><div className="input-prefix"><i>NT$</i><input required name="budget" type="number" min="0" step="1" inputMode="numeric" defaultValue={campaign?.base_budget??campaign?.budget??5000} onFocus={e=>e.currentTarget.select()} onWheel={e=>e.currentTarget.blur()}/></div><small>此欄為本期基本預算，不包含上期結轉。</small></label><div className="rollover-field"><span>本期未用預算</span><input type="hidden" name="retain_unused_budget" value={String(retainUnused)}/><button type="button" className={`budget-choice ${retainUnused?"selected":""}`} role="switch" aria-checked={retainUnused} onClick={()=>setRetainUnused(x=>!x)}><b>↓</b><span><strong>保留至下一期</strong><small>決定本期剩餘的錢是否留下</small></span><em>{retainUnused?"已開啟":"不保留"}</em></button></div><div className="rollover-field"><span>上期保留預算</span><input type="hidden" name="carryover_enabled" value={String(usePrevious)}/><button type="button" className={`budget-choice ${usePrevious?"selected":""}`} role="switch" aria-checked={usePrevious} onClick={()=>setUsePrevious(x=>!x)}><b>＋</b><span><strong>加入本期使用</strong><small>上一期必須先選擇保留才會有金額</small></span><em>{usePrevious?"已開啟":"不使用"}</em></button>{usePrevious&&campaign?.carryover_enabled&&<p className="rollover-summary">目前使用 NT$ {Number(campaign.carryover_amount).toLocaleString()}，可用總額 NT$ {Number(campaign.budget).toLocaleString()}</p>}</div><label><span>開始</span><input required name="start_at" type="datetime-local" defaultValue={campaign?dateTimeInput(campaign.start_at):dateTimeInput(defaults.start.toISOString())}/></label><label><span>提名截止</span><input required name="nomination_deadline" type="datetime-local" defaultValue={campaign?dateTimeInput(campaign.nomination_deadline):dateTimeInput(defaults.nomination.toISOString())}/></label><label><span>投票截止</span><input required name="voting_deadline" type="datetime-local" defaultValue={campaign?dateTimeInput(campaign.voting_deadline):dateTimeInput(defaults.voting.toISOString())}/></label><label><span>安排採購</span><input required name="purchase_at" type="datetime-local" defaultValue={campaign?dateTimeInput(campaign.purchase_at):dateTimeInput(defaults.purchase.toISOString())}/></label><label><span>每人提名上限</span><input required name="nomination_limit" type="number" min="1" defaultValue={campaign?.nomination_limit??2}/><small>提名項目會各固定占用一票</small></label><label><span>每人總票數上限</span><input required name="vote_limit" type="number" min="1" defaultValue={campaign?.vote_limit??4}/><small>不得少於提名上限</small></label><label><span>發布狀態</span><select name="status" defaultValue={campaign?.status??"active"}><option value="draft">草稿（員工不可見）</option><option value="active">啟用</option><option value="archived">封存</option></select></label></div><div className="form-footer"><div className="rule-note"><strong>參與名單</strong><span>建立新活動時會納入所有啟用員工；建立後可在下方逐一調整，不會因修改日期而被重設。</span></div><button className="solid-button" disabled={busy}>{busy?"儲存中…":"儲存活動設定"}</button></div></form></section>}

function CampaignMemberPanel({campaign,employees,members,onToggle}:{campaign:Campaign;employees:Employee[];members:CampaignMember[];onToggle:(employee:Employee)=>void}){const rows=members.filter(m=>m.campaign_id===campaign.id);const eligibleEmployees=employees.filter(e=>e.work_location_id===campaign.work_location_id);const activeCount=rows.filter(m=>m.active&&eligibleEmployees.some(e=>e.id===m.employee_id)).length;return <section className="admin-card"><div className="card-title"><div><p className="section-kicker">CAMPAIGN MEMBERS</p><h2>本期參與名單</h2></div><span className="count-tag">{activeCount} 人參與</span></div><p className="panel-help">只列出與本活動相同上班地點的員工。調整只影響「{campaign.label}」，不會改動員工帳號或其他期別。</p><div className="member-grid">{eligibleEmployees.map(row=>{const member=rows.find(m=>m.employee_id===row.id);const checked=member?.active??false;return <button type="button" key={row.id} className={checked?"selected":""} role="switch" aria-checked={checked} onClick={()=>onToggle(row)}><span className="avatar small">{row.name.slice(0,1)}</span><span><strong>{row.name}</strong><small>{row.email}</small></span><em>{checked?"本期參與":"本期排除"}</em></button>})}</div></section>}

function WorkLocationManager({locations,employees,campaigns,onAdd,onRename,onDelete,onToggle}:{locations:WorkLocation[];employees:Employee[];campaigns:Campaign[];onAdd:(name:string)=>void;onRename:(row:WorkLocation,name:string)=>void;onDelete:(row:WorkLocation)=>void;onToggle:(row:WorkLocation)=>void}){const [name,setName]=useState("");const [drafts,setDrafts]=useState<Record<string,string>>({});useEffect(()=>setDrafts(Object.fromEntries(locations.map(x=>[x.id,x.name]))),[locations]);return <section className="admin-card location-manager"><div className="card-title"><div><p className="section-kicker">WORK LOCATIONS</p><h2>上班地點</h2></div><span className="count-tag">{locations.length} 處</span></div><p className="panel-help">員工與活動都必須指定地點；同一時間可為不同地點建立各自的活動。</p><form className="category-add" onSubmit={e=>{e.preventDefault();if(name.trim()){onAdd(name);setName("")}}}><input value={name} onChange={e=>setName(e.target.value)} placeholder="例如：台北辦公室"/><button>＋ 新增地點</button></form><div className="location-list">{locations.map(row=>{const employeeCount=employees.filter(e=>e.work_location_id===row.id).length;const campaignCount=campaigns.filter(c=>c.work_location_id===row.id).length;return <article key={row.id}><span className="location-pin">⌖</span><input value={drafts[row.id]??row.name} onChange={e=>setDrafts(x=>({...x,[row.id]:e.target.value}))}/><span>{employeeCount} 位員工 · {campaignCount} 期活動</span><div><button disabled={(drafts[row.id]??row.name).trim()===row.name} onClick={()=>onRename(row,drafts[row.id]??row.name)}>儲存名稱</button><button onClick={()=>onToggle(row)}>{row.active?"停用":"啟用"}</button><button className="danger" onClick={()=>onDelete(row)}>刪除</button></div></article>})}</div></section>}

function CategoryManager({categories,products,nominations,votes,currentCampaigns,busy,onAdd,onRename,onDelete}:{categories:ProductCategory[];products:Product[];nominations:Nomination[];votes:Vote[];currentCampaigns:Campaign[];busy:boolean;onAdd:(name:string)=>void;onRename:(row:ProductCategory,name:string)=>void;onDelete:(row:ProductCategory)=>void}){
  const [newName,setNewName]=useState("");const [drafts,setDrafts]=useState<Record<string,string>>({});
  useEffect(()=>{setDrafts(Object.fromEntries(categories.map(c=>[c.id,c.name])))},[categories]);
  function submit(event:FormEvent){event.preventDefault();const clean=newName.trim();if(!clean)return;onAdd(clean);setNewName("")}
  return <section className="admin-card category-manager"><div className="card-title"><div><p className="section-kicker">PRODUCT CATEGORIES</p><h2>商品類別</h2></div><span className="count-tag">{categories.length} 類</span></div><p className="panel-help">新增或改名後，員工端與所有商品表單會立即同步。刪除類別會一併移除其中商品，但不破壞過往活動紀錄。</p><form className="category-add" onSubmit={submit}><input value={newName} onChange={e=>setNewName(e.target.value)} maxLength={80} placeholder="輸入新類別名稱"/><button disabled={busy||!newName.trim()}>＋ 新增類別</button></form><div className="category-admin-list">{categories.map(row=>{const related=products.filter(p=>p.category===row.name);const ids=new Set(related.map(p=>p.id));const activeIds=new Set(currentCampaigns.map(c=>c.id));const used=[...nominations,...votes].some(x=>activeIds.has(x.campaign_id)&&ids.has(x.product_id));const draft=drafts[row.id]??row.name;return <article key={row.id} className={used?"protected":""}><span className="category-symbol">{icons[row.name]??"✦"}</span><label><small>類別名稱</small><input value={draft} maxLength={80} onChange={e=>setDrafts(x=>({...x,[row.id]:e.target.value}))}/></label><span className="category-count"><strong>{related.length}</strong> 項商品</span>{used&&<span className="category-lock">活動使用中</span>}<div><button disabled={busy||!draft.trim()||draft.trim()===row.name} onClick={()=>onRename(row,draft)}>儲存名稱</button><button className="danger" disabled={busy||used} title={used?"進行中的活動已有商品被提名或投票，不可刪除":"刪除類別與其中商品"} onClick={()=>onDelete(row)}>刪除</button></div></article>})}</div></section>
}

function ProductEditor({product,categories,busy,onClose,onSave}:{product:Product;categories:ProductCategory[];busy:boolean;onClose:()=>void;onSave:(form:FormData,image:File|null)=>void}){
  const {ask:askConfirm,element:confirmElement}=useConfirmDialog();
  const [dirty,setDirty]=useState(false);const [image,setImage]=useState<File|null>(null);const [preview,setPreview]=useState(productImageUrl(product.image_path));const [removeImage,setRemoveImage]=useState(false);
  async function requestClose(){if(!dirty||await askConfirm({title:"放棄尚未儲存的修改？",items:["關閉後，本次編輯的文字與圖片變更都不會保留。"],confirmLabel:"放棄修改",danger:true}))onClose()}
  useEffect(()=>{const handle=(event:KeyboardEvent)=>{if(event.key==="Escape")requestClose()};window.addEventListener("keydown",handle);return()=>window.removeEventListener("keydown",handle)},[dirty]);
  useEffect(()=>{const warn=(event:BeforeUnloadEvent)=>{if(!dirty)return;event.preventDefault();event.returnValue=""};window.addEventListener("beforeunload",warn);return()=>window.removeEventListener("beforeunload",warn)},[dirty]);
  useEffect(()=>()=>{if(preview.startsWith("blob:"))URL.revokeObjectURL(preview)},[preview]);
  function selectImage(file:File|null){if(!file)return;if(file.size>5*1024*1024){alert("圖片不可超過 5MB");return}if(!["image/jpeg","image/png","image/webp","image/gif"].includes(file.type)){alert("僅支援 JPG、PNG、WebP 或 GIF 圖片");return}if(preview.startsWith("blob:"))URL.revokeObjectURL(preview);setImage(file);setPreview(URL.createObjectURL(file));setRemoveImage(false);setDirty(true)}
  function remove(){if(preview.startsWith("blob:"))URL.revokeObjectURL(preview);setImage(null);setPreview("");setRemoveImage(true);setDirty(true)}
  function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);form.set("remove_image",String(removeImage));onSave(form,image)}
  return <div className="editor-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)requestClose()}}><section className="product-editor" role="dialog" aria-modal="true" aria-labelledby="product-editor-title"><header><div><p className="section-kicker">PRODUCT EDITOR</p><h2 id="product-editor-title">編輯商品資料</h2><span>{product.origin==="employee"?"同仁新增":"管理者商品庫"} · {product.approval_status==="approved"?"已核准":product.approval_status==="pending"?"待審核":"已退回"}</span></div><button type="button" onClick={requestClose} aria-label="關閉編輯視窗">×</button></header><form onSubmit={submit} onChange={()=>setDirty(true)}><div className="editor-layout"><div className="editor-image"><div className="editor-preview">{preview?<img src={preview} alt="商品圖片預覽"/>:<span>{icons[product.category]??"✦"}<small>尚無商品圖</small></span>}</div><label className="image-change">上傳或更換圖片<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" onChange={e=>selectImage(e.target.files?.[0]??null)}/></label>{preview&&<button type="button" className="remove-image" onClick={remove}>移除圖片</button>}<small>JPG、PNG、WebP、GIF，最大 5MB</small></div><div className="editor-fields"><label className="field-wide"><span>商品名稱 *</span><input required name="name" defaultValue={product.name} maxLength={160}/></label><label><span>品牌</span><input name="brand" defaultValue={product.brand} maxLength={80}/></label><label><span>分類 *</span><select required name="category" defaultValue={product.category}>{categories.map(c=><option key={c.id} value={c.name}>{c.name}</option>)}</select></label><label><span>規格</span><input name="size" defaultValue={product.size} maxLength={80} placeholder="例如 100g、12入"/></label><label><span>參考價格</span><div className="editor-price"><i>NT$</i><input name="reference_price" type="number" min="0" step="1" defaultValue={product.reference_price??""} placeholder="留空表示待確認"/></div></label><label className="field-wide"><span>商品狀態</span><select name="active" defaultValue={String(product.active)}><option value="true">啟用－員工可在商品庫看到</option><option value="false">停用－保留歷史但不供新提名</option></select></label></div></div><footer><div>{dirty?<><span className="unsaved-dot"/>尚有未儲存的修改</>:"目前沒有修改"}</div><button type="button" className="editor-cancel" onClick={requestClose}>取消</button><button className="editor-save" disabled={busy||!dirty}>{busy?"儲存中…":"儲存商品"}</button></footer></form></section>{confirmElement}</div>
}

function PurchasePanel({campaign,products,purchases,onGenerate,onUpdate}:{campaign:Campaign|null;products:Product[];purchases:PurchaseItem[];onGenerate:()=>void;onUpdate:(row:PurchaseItem,patch:Partial<PurchaseItem>)=>void}){if(!campaign)return <section className="admin-card"><div className="admin-empty">請先建立本期活動。</div></section>;const rows=purchases.filter(p=>p.campaign_id===campaign.id);const total=rows.reduce((sum,row)=>sum+Number(row.unit_price)*Number(row.final_quantity??row.suggested_quantity),0);const remaining=Number(campaign.budget)-total;return <><div className="purchase-summary"><div><span>本期可用預算 · {campaign.label}</span><strong>NT$ {Number(campaign.budget).toLocaleString()}</strong><small>基本 NT$ {Number(campaign.base_budget??campaign.budget).toLocaleString()}{campaign.carryover_enabled?` ＋ 使用上期保留 NT$ ${Number(campaign.carryover_amount).toLocaleString()}`:" · 未使用上期保留"}{campaign.retain_unused_budget?" · 本期餘額將保留":" · 本期餘額不保留"}</small></div><div><span>目前清單金額</span><strong>NT$ {total.toLocaleString()}</strong></div><div className={remaining<0?"over-budget":""}><span>{remaining<0?"超出預算":"預算餘額"}</span><strong>NT$ {Math.abs(remaining).toLocaleString()}</strong></div></div><section className="admin-card"><div className="card-title"><div><p className="section-kicker">PURCHASE PLAN</p><h2>{campaign.label} 採購清單</h2></div><button className="solid-button" onClick={onGenerate}>{rows.length?"重新計算建議":"產生採購建議"}</button></div><div className="rule-note purchase-rule"><strong>分配規則</strong><span>只取前 5 名，先依排名每項最多 2 份；剩餘預算再由第 1 名到第 5 名逐輪加購，直到餘額買不起任何品項。未設定價格的商品會暫停分配。</span></div>{rows.length?<div className="table-wrap"><table><thead><tr><th>排名</th><th>商品</th><th>票數</th><th>採購單價</th><th>採購數量</th><th>小計</th><th>完成</th></tr></thead><tbody>{rows.map(row=>{const product=products.find(p=>p.id===row.product_id);const qty=row.final_quantity??row.suggested_quantity;return <tr key={row.id}><td><strong>#{row.rank}</strong></td><td>{product?`${product.brand} ${product.name}`:"商品資料已移除"}{row.unit_price<=0&&<small className="cell-warning">尚未設定價格</small>}</td><td>{row.vote_count} 票</td><td><input className="price-input" type="number" min="0" value={row.unit_price} onChange={e=>onUpdate(row,{unit_price:Number(e.target.value)})}/></td><td><input className="qty-input" type="number" min="0" value={qty} onChange={e=>onUpdate(row,{final_quantity:Number(e.target.value)})}/></td><td>NT$ {(Number(row.unit_price)*qty).toLocaleString()}</td><td><label className="check-label"><input type="checkbox" checked={row.purchased} onChange={e=>onUpdate(row,{purchased:e.target.checked})}/>{row.purchased?"已買":"未買"}</label></td></tr>})}</tbody></table></div>:<div className="admin-empty">投票結束後，按「產生採購建議」。請先在商品資料庫確認前五名商品的參考價格。</div>}</section></>}

function HistoryPanel({campaigns,locations,products,nominations,votes,comments,purchases,onEdit,onDelete}:{campaigns:Campaign[];locations:WorkLocation[];products:Product[];nominations:Nomination[];votes:Vote[];comments:Comment[];purchases:PurchaseItem[];onEdit:(campaign:Campaign)=>void;onDelete:(campaign:Campaign)=>void}){const [expanded,setExpanded]=useState<string|null>(null);return <section className="admin-card"><div className="card-title"><div><p className="section-kicker">CAMPAIGN HISTORY</p><h2>所有活動完整紀錄</h2></div><span className="count-tag">{campaigns.length} 期</span></div>{campaigns.length?<div className="history-detail-list">{campaigns.map(c=>{const cv=votes.filter(v=>v.campaign_id===c.id);const cn=nominations.filter(n=>n.campaign_id===c.id);const cc=comments.filter(x=>x.campaign_id===c.id);const cp=purchases.filter(x=>x.campaign_id===c.id);const productIds=[...new Set([...cn.map(n=>n.product_id),...cv.map(v=>v.product_id),...cp.map(p=>p.product_id)])];const ranking=productIds.map(id=>({id,count:cv.filter(v=>v.product_id===id).length})).sort((a,b)=>b.count-a.count||a.id.localeCompare(b.id));const spent=cp.reduce((sum,x)=>sum+Number(x.unit_price)*Number(x.final_quantity??x.suggested_quantity),0);const open=expanded===c.id;return <article className={`history-detail ${open?"open":""}`} key={c.id}><button className="history-summary" onClick={()=>setExpanded(open?null:c.id)}><span><em>{c.status==="archived"?"已封存":phaseLabel(phaseOf(c))}</em><strong>{c.label}</strong><small>{locations.find(x=>x.id===c.work_location_id)?.name??"未設定地點"} · {shortDate(c.start_at)}－{shortDate(c.purchase_at)}</small></span><span><b>預算 NT$ {Number(c.budget).toLocaleString()}</b><small>{cv.length} 票 · {cn.length} 筆提名 · {cc.length} 則留言</small></span><i>{open?"收合":"查看完整紀錄"}</i></button>{open&&<div className="history-body"><div className="history-maintain"><div><button onClick={()=>onEdit(c)}>維護此活動設定</button><button className="history-delete" onClick={()=>onDelete(c)}>強制刪除活動</button></div><span>修改預算、日期、地點或狀態；既有投票與採購紀錄會保留。</span></div><div className="history-metrics"><span>預算<strong>NT$ {Number(c.budget).toLocaleString()}</strong></span><span>採購清單金額<strong>NT$ {spent.toLocaleString()}</strong></span><span>已完成採購<strong>{cp.filter(x=>x.purchased).length} 項</strong></span></div><div className="table-wrap"><table><thead><tr><th>排名</th><th>商品</th><th>提名者</th><th>票數與投票者</th><th>留言</th><th>採購結果</th></tr></thead><tbody>{ranking.map((r,index)=>{const product=products.find(p=>p.id===r.id);const ns=cn.filter(n=>n.product_id===r.id);const vs=cv.filter(v=>v.product_id===r.id);const cs=cc.filter(x=>x.product_id===r.id);const buy=cp.find(x=>x.product_id===r.id);return <tr key={r.id}><td><strong>#{index+1}</strong></td><td>{product?`${product.brand} ${product.name}`:"商品資料已停用"}</td><td>{ns.map(n=>n.nominator_name).join("、")||"—"}</td><td><strong>{vs.length} 票</strong><small className="cell-sub">{vs.map(v=>v.voter_name).join("、")||"—"}</small></td><td>{cs.length?<details><summary>{cs.length} 則</summary>{cs.map(x=><p className="history-comment" key={x.id}><b>{x.author_name}</b>{x.body}</p>)}</details>:"—"}</td><td>{buy?`${buy.final_quantity??buy.suggested_quantity} 份 · NT$ ${(Number(buy.unit_price)*Number(buy.final_quantity??buy.suggested_quantity)).toLocaleString()}${buy.purchased?" · 已買":""}`:"未列入"}</td></tr>})}</tbody></table></div></div>}</article>})}</div>:<div className="admin-empty">尚無活動紀錄。</div>}</section>}
